-- ATV tours are edited in CALA ("ATV Tours") and rendered by the public
-- /tours page. The texts, galleries and order that used to live in the site's
-- static dictionary move next to the price in site.tour_destinations, so a
-- tour added, edited or removed in CALA shows on the website at once.
-- `name` / `description` keep their old meaning (booking modal, invoices):
-- the editor writes them together with the bilingual titles.
alter table site.tour_destinations
 add column slug text,
 add column title_es text,add column title_en text,
 add column summary_es text,add column summary_en text,
 add column long_es text,add column long_en text,
 add column duration_es text,add column duration_en text,
 add column capacity_es text,add column capacity_en text,
 add column includes_es jsonb not null default '[]'::jsonb check(jsonb_typeof(includes_es)='array'),
 add column includes_en jsonb not null default '[]'::jsonb check(jsonb_typeof(includes_en)='array'),
 add column images jsonb not null default '[]'::jsonb check(jsonb_typeof(images)='array'),
 add column sort_order integer not null default 0;
grant select,insert,update,delete on site.tour_destinations to cala_site_app;

-- The seven tours currently published on /tours, exactly as shown today.
update site.tour_destinations set slug='ATV_OJO_DE_AGUA',sort_order=1,
 title_es='Ojo de Agua',title_en='Ojo de Agua',
 summary_es='Huertos hacia un manantial prístino de agua fría. Descubre petroglifos ocultos.',summary_en='Orchards leading to a pristine cold water spring. Discover hidden petroglyphs.',
 long_es='Ojo de Agua es un paraíso selvático de agua dulce. Relativamente cerca de Chacala en distancia, recorremos extensamente la zona antes de llegar. Saliendo hacia el sur justo a las afueras de Chacala transitamos por los hermosos huertos de mangos y guanábanas de El Divisadero y sus alrededores. A lo lejos se puede ver el pueblo montañoso de Alta Vista, así como las playas de Guayabitos y La Peñita. Esta experiencia al aire libre seguramente refrescará tus sentidos y te reconectará con la naturaleza.',
 long_en='Ojo De Agua is a sweet water Jungle Paradise! Located relatively close to Chacala in distance we tour the area extensively before arriving. Turning south just outside of Chacala we transit through the beautiful Mango and Guanabana orchards of El Divisidaro and surrounding area. In the distance you can see the mountain town of Alta Vista as well as the beaches of Guayabitos & La Penita. This open air experience is sure to refresh your senses and get you reconnected with nature.',
 duration_es='3-4 hrs',duration_en='3-4 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Accesorios de playa","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Beach Accessories","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743843/hotelsonador/tours_gallery/01_ojo_de_agua/00_ojoagua_002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743834/hotelsonador/tours_gallery/01_ojo_de_agua/01_ojoagua_001.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743835/hotelsonador/tours_gallery/01_ojo_de_agua/02_ojoagua_012.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743837/hotelsonador/tours_gallery/01_ojo_de_agua/03_ojoagua_003.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743841/hotelsonador/tours_gallery/01_ojo_de_agua/04_ojoagua_015.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743846/hotelsonador/tours_gallery/01_ojo_de_agua/05_ojoagua_014.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743840/hotelsonador/tours_gallery/01_ojo_de_agua/06_ojoagua_004.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743830/hotelsonador/tours_gallery/01_ojo_de_agua/07_ojoagua_005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743832/hotelsonador/tours_gallery/01_ojo_de_agua/08_ojoagua_008.webp"]'::jsonb
 where id=1 and title_es is null;
update site.tour_destinations set slug='ATV_RIO_MOLOTE',sort_order=2,
 title_es='Río Molote',title_en='Río Molote',
 summary_es='Entradas termales y refrescantes aguas río abajo.',summary_en='Thermal inlets and refreshing downstream river waters.',
 long_es='Mesillas es un pequeño pueblo a 25km al norte de Chacala con una red de ríos de aguas termales. Dejando Chacala viajamos 18km al norte hacia Mesillas con un aumento de elevación de aproximadamente 1500 pies. Desde Mesillas descendemos al fondo del valle por una serie de curvas montañosas. ¡Las vistas en este tramo son espectaculares! Una vez en el río, caminamos 1.5 km por un laberinto de afluentes termales. Hay pozas excavadas en el río ideales para sumergirse. De regreso, conducimos por el fondo del valle hasta Zacualpan, cruzando algunas de las tierras de cultivo más ricas y fértiles del estado.',
 long_en='Mesillas is a small town 25km north of Chacala with a thermal spring river network. Leaving Chacala via highway 200 we travel 18 kms north to Mesillas. From Mesillas we descend to the valley floor using a series of mountain switchbacks. Once at the river we disembark and start our hike. The 1.5 km walk is a maze of thermal tributaries entering the main channel. There are a series of dug outs in the river that are used as wading pools. From here we drive out the valley floor over to Zacualpan witnessing some of the richest farmland in the state.',
 duration_es='6-8 hrs',duration_en='6-8 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743848/hotelsonador/tours_gallery/02_molote_river/00_molote_002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743854/hotelsonador/tours_gallery/02_molote_river/01_molote_001.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743863/hotelsonador/tours_gallery/02_molote_river/02_molote_003.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743859/hotelsonador/tours_gallery/02_molote_river/03_molote_004.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743861/hotelsonador/tours_gallery/02_molote_river/04_molote_005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743852/hotelsonador/tours_gallery/02_molote_river/05_molote_006.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743857/hotelsonador/tours_gallery/02_molote_river/06_molote_007.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743850/hotelsonador/tours_gallery/02_molote_river/07_molote_008.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743856/hotelsonador/tours_gallery/02_molote_river/08_molote_010.webp"]'::jsonb
 where id=2 and title_es is null;
update site.tour_destinations set slug='ATV_EL_CAPOMO',sort_order=3,
 title_es='El Capomo',title_en='El Capomo',
 summary_es='Piscina natural bajo una majestuosa cascada en la jungla.',summary_en='Natural plunge pool under a majestic 50ft jungle waterfall.',
 long_es='Este tour a la comunidad agrícola de El Capomo es la oportunidad perfecta para entrar al agua y refrescarse. Conducimos campo a través por los huertos de El Divisadero para llegar al pueblo de El Capomo, donde hacemos un recorrido rápido antes de dirigirnos a las faldas de la montaña, paralelos al río. Las cascadas de El Capomo requieren caminar por el lecho del río durante aproximadamente 1km hasta llegar a la poza profunda donde puedes nadar bajo la cascada.',
 long_en='This tour to the farming community of El Capomo is the perfect opportunity to get in the water and cool down. We ride cross country through the orchards of El Divisidaro to get to the town of El Capomo where we do a quick tour of town. Then it is off into the foothills where we parallel the lazy river until we come to our parking area. El Capomo falls requires you to walk up the river bed for approximately 1km until we reach the plunge pool where you can swim under the falls.',
 duration_es='4-5 hrs',duration_en='4-5 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743810/hotelsonador/tours_gallery/03_el_capomo/00_capomof001.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743824/hotelsonador/tours_gallery/03_el_capomo/01_capomof003.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743817/hotelsonador/tours_gallery/03_el_capomo/02_capomof002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743815/hotelsonador/tours_gallery/03_el_capomo/03_capomof008.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743828/hotelsonador/tours_gallery/03_el_capomo/04_capomof006.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743821/hotelsonador/tours_gallery/03_el_capomo/05_capomof005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743814/hotelsonador/tours_gallery/03_el_capomo/06_capomof011.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743819/hotelsonador/tours_gallery/03_el_capomo/07_capomof010.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743822/hotelsonador/tours_gallery/03_el_capomo/08_capomof009.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743826/hotelsonador/tours_gallery/03_el_capomo/09_capomof004.webp"]'::jsonb
 where id=3 and title_es is null;
update site.tour_destinations set slug='ATV_LAS_CUEVAS',sort_order=4,
 title_es='Las Cuevas',title_en='Las Cuevas',
 summary_es='Playa secreta bajo un tapón volcánico para disfrutar sin interrupciones.',summary_en='Hidden gem under a volcanic plug for uninterrupted beach time.',
 long_es='Ubicada a 1 hora de viaje desde Chacala, esta playa relativamente desconocida es un lugar donde el agua se ha mezclado con el fuego y ambos han dejado su huella en la tierra. Rocas volcánicas cubren el área y la lava que una vez fluyó aquí todavía es visible. Ubicada en una caleta bajo un tapón volcánico, la energía de la tierra es fuerte y los practicantes de trabajo energético querrán explorar este lugar. Las Cuevas es ideal para grupos que buscan pasar un día de playa sin interferencias.',
 long_en='Located 1hr. ride from Chacala this relatively unknown beach is a place where water has mixed with fire and both have left their mark upon the earth. Volcanic rock litters the area and the lava that once flowed here is still visible. Nestled in a cove below a volcanic plug the energy of the earth is strong and practitioners looking to perform energy type work will want to scout this location. Los Cuevas is Ideal for groups looking to spend some time at the beach without a lot of interference.',
 duration_es='4-6 hrs',duration_en='4-6 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Sombrillas y sillas de playa","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Beach umbrellas and chairs","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743793/hotelsonador/tours_gallery/04_las_cuevas/01_loscuevas016.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743786/hotelsonador/tours_gallery/04_las_cuevas/02_loscuevas005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743781/hotelsonador/tours_gallery/04_las_cuevas/03_loscuevas002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743783/hotelsonador/tours_gallery/04_las_cuevas/04_loscuevas012.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743784/hotelsonador/tours_gallery/04_las_cuevas/05_loscuevas014.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743792/hotelsonador/tours_gallery/04_las_cuevas/06_loscuevas010.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743788/hotelsonador/tours_gallery/04_las_cuevas/07_loscuevas009.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743779/hotelsonador/tours_gallery/04_las_cuevas/08_loscuevas007.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743789/hotelsonador/tours_gallery/04_las_cuevas/09_loscuevas003.webp"]'::jsonb
 where id=4 and title_es is null;
update site.tour_destinations set slug='ATV_JUMURRCA',sort_order=5,
 title_es='Jumurrca',title_en='Jumurrca',
 summary_es='Explora un hermoso balneario moderno en medio de la naturaleza.',summary_en='Explore hidden paths and spectacular views of local wildlife.',
 long_es='Las aguas termales de Jumurrca es una hermosa instalación moderna y actualizada. Jumurrca cuenta con 2 piscinas principales, un jacuzzi superior y 2 piscinas para niños con sombrillas. Esta instalación tiene refugios estilo cabaña paralelos a ambos lados de las áreas de la piscina, completos con sillas y mesas. Hay varias áreas verdes creando separación y privacidad. Al fondo de la instalación hay una hermosa área común con altas palmeras. No se agregan productos químicos a las aguas; las piscinas se enjuagan y limpian regularmente.',
 long_en='Jumurrca Agua''s Terminales is a beautiful up to date modern facility. Jumurrca boasts 2 main pools, an upper hot tub and 2 lower wading pools with sun shades for kids of all ages. This facility has cabana style shelters paralleling both sides of the pool areas. There are several grassy areas with walk ways creating separation allowing for privacy. At the far end of the facility there is a beautiful common area with high palm trees producing shade. No chemical is added to the waters and pools are flushed regularly.',
 duration_es='4-5 hrs',duration_en='4-5 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743761/hotelsonador/tours_gallery/05_jamurrca/00_jumurrca001.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743754/hotelsonador/tours_gallery/05_jamurrca/01_jumurrca002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743745/hotelsonador/tours_gallery/05_jamurrca/02_jumurrca006.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743756/hotelsonador/tours_gallery/05_jamurrca/03_jumurrca008.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743752/hotelsonador/tours_gallery/05_jamurrca/04_jumurrca004.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743751/hotelsonador/tours_gallery/05_jamurrca/05_jumurrca005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743747/hotelsonador/tours_gallery/05_jamurrca/06_jumurrca007.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743759/hotelsonador/tours_gallery/05_jamurrca/07_jumurrca009.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743763/hotelsonador/tours_gallery/05_jamurrca/08_jumurrca003.webp"]'::jsonb
 where id=5 and title_es is null;
update site.tour_destinations set slug='ATV_ALTA_VISTA',sort_order=6,
 title_es='Alta Vista',title_en='Alta Vista',
 summary_es='Antiguos petroglifos y sitios sagrados en la exuberante jungla.',summary_en='Ancient petroglyphs and sacred sites hidden in Nayarit''s lush jungle.',
 long_es='Alta Vista es un complejo de petroglifos que se originó en una época anterior a la historia registrada. Este sitio ha sido utilizado por los pueblos en busca de conexión espiritual e iluminación durante miles de años. Los tallados en estas rocas son indicadores de las energías de la naturaleza y sirven como mapas de carreteras para las generaciones venideras, indicando recursos estacionales. También hay evidencia de la conquista española del siglo XVI. Es un lugar imperdible para interesados en culturas antiguas.',
 long_en='Alta Vista is a Petroglyph Complex originating at a time that existed before recorded history. This site has been used by peoples'' seeking spiritual connection and enlightenment for thousands of years. The carvings on these rocks are indicators of the energies that exist in nature and double as seasonal calendars. Also at this site is evidence of the Spanish conquest of Mexico dating to the early 16th century. This is a must see location for anyone interested in ancient cultures and civilizations.',
 duration_es='4-5 hrs',duration_en='4-5 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Entradas incluidas","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Entry Fees Included","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743802/hotelsonador/tours_gallery/06_alta_vista/00_altavista_002.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743807/hotelsonador/tours_gallery/06_alta_vista/01_altavista_010.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743794/hotelsonador/tours_gallery/06_alta_vista/02_altavista_004.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743806/hotelsonador/tours_gallery/06_alta_vista/03_altavista_005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743804/hotelsonador/tours_gallery/06_alta_vista/04_altavista_007.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743800/hotelsonador/tours_gallery/06_alta_vista/05_altavista_006.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743796/hotelsonador/tours_gallery/06_alta_vista/06_altavista_001.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743798/hotelsonador/tours_gallery/06_alta_vista/07_altavista_003.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743809/hotelsonador/tours_gallery/06_alta_vista/08_alta_vista009.webp"]'::jsonb
 where id=6 and title_es is null;
update site.tour_destinations set slug='ATV_VOLCANO',sort_order=7,
 title_es='Volcán',title_en='Volcano Sunset',
 summary_es='Conquista el cráter y experimenta impresionantes vistas panorámicas al atardecer.',summary_en='Conquer the crater and experience breathtaking panoramic sunset views.',
 long_es='Si visitas Chacala definitivamente no querrás perderte el momento más mágico del día... ¡El atardecer! Hacemos un hermoso recorrido nocturno por la jungla y huertos de Chacala hasta la cima del volcán que domina la bahía. Desde aquí tienes una vista despejada de un espectáculo que dura más de 30 minutos. Ven con nosotros al borde del mundo donde la tierra se encuentra con el mar, observa las energías del Sol y la Luna bailar sobre el agua bajo las estrellas.',
 long_en='If you are visiting Chacala you definitely do not want to miss out on the most magical time of day... Sunset !!! Chacala Adventure Tours does a beautiful evening cruise through the jungle and orchards of Chacala to the top of the Volcano that over looks Chacala Bay. From here you have an unobstructed view of a spectacle that can last more than 30 minutes. Watch as the energies of Sun and Moon dance upon the water and reflect in the sky as the stars come to greet the evening.',
 duration_es='2-3 hrs',duration_en='2-3 hrs',
 capacity_es='Máximo 5 pasajeros por unidad (hasta 10 por grupo)',capacity_en='Maximum 5 passengers per unit (up to 10 per group)',
 includes_es='["Hielera con agua y hielo","Guía/Conductor"]'::jsonb,includes_en='["Cooler with ice & water","Guide/Driver"]'::jsonb,
 images='["https://res.cloudinary.com/p6nhvksw/image/upload/v1784743773/hotelsonador/tours_gallery/07_volcano/00_sunset_019.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743770/hotelsonador/tours_gallery/07_volcano/01_sunset_006.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743768/hotelsonador/tours_gallery/07_volcano/02_sunset_008.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743764/hotelsonador/tours_gallery/07_volcano/03_sunset_015.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743776/hotelsonador/tours_gallery/07_volcano/04_sunset_017.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743766/hotelsonador/tours_gallery/07_volcano/05_sunset_005.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743772/hotelsonador/tours_gallery/07_volcano/06_sunset_011.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743769/hotelsonador/tours_gallery/07_volcano/07_sunset_016.webp","https://res.cloudinary.com/p6nhvksw/image/upload/v1784743778/hotelsonador/tours_gallery/07_volcano/08_sunset_009.webp"]'::jsonb
 where id=7 and title_es is null;
